function motherSession(c){const claims=ncDecodeJwt(ncCookie(c.req.raw,'__Host-mecopay_jwt')); if(!claims||claims.surface!=='mother'||claims.domain!=='mecopay.space'||claims.exp<=Math.floor(Date.now()/1000)) return null; return ncJson(c,{session:{id:claims.jti,expiresAt:new Date(claims.exp*1000).toISOString()},user:{id:claims.sub,name:claims.name||'MecoPay User',email:claims.email||'',emailVerified:true,image:claims.image||null}});}
function motherSignOut(c){const r=ncJson(c,{ok:true,status:'signed_out'}); r.headers.append('Set-Cookie','__Host-mecopay_jwt=; Max-Age=0; Path=/; Secure; HttpOnly; SameSite=Lax'); return r;}

